INSERT INTO public.service_categories(slug,name,intro,sort_order) VALUES
('video-ads','Video ads','Story-led and performance video ads, made without a shoot.',1),
('imagery','Product and fashion imagery','Product, catalogue and fashion images that look professionally shot.',2),
('people','People and presenters','Faces, presenters and digital twins for your brand.',3),
('social','Social content and editing','Reels, motion graphics and editing that keep your page alive.',4),
('voice','Voice and sound','Voice, music and sound that make your brand heard.',5),
('strategy','Strategy and brand','The thinking before and after the ad, so your budget works harder.',6);
INSERT INTO public.services(slug,name,category,short_description,full_description,deliverables,price_min,price_max,price_unit,base_currency,pricing_model,is_published,is_featured,is_new,sort_order,best_for,signs_you_need_it,what_we_need,formats,delivery,goals,related,compare_note,hero_title,hero_media) VALUES
('ai-commercial-30s','AI Commercial, 30s','video-ads','A full story-led commercial with locked characters and locations, made without a shoot.','A complete TV and social commercial built with AI. The same characters and locations stay consistent from the first frame to the last, so it feels like a real production.',ARRAY['Concept and full script','Character and location sheets so every scene stays consistent','30s master film','3 cutdowns: 15s, 6s and a 9:16 vertical','Captions in Bangla or English']::text[],290,440,'project','USD','quote',true,true,false,1,ARRAY['FMCG, beverage and snack brands','Skincare and cosmetics','Real estate and banking','Any brand launching a main campaign']::text[],ARRAY['You are launching a new product or campaign','You want TVC quality without a TVC shoot budget','You want people to remember a story, not just an offer']::text[],ARRAY['Product photos or a sample','Logo and brand colours','Who your customer is','Your main offer or message']::text[],'16:9, 9:16, 1:1','7 days',ARRAY['sales','launch','brand','festival']::text[],ARRAY['ai-commercial-60s','cgi-product-commercial']::text[],NULL,'{"lead":"Your next TV ad,","accent":"shoot-free","rest":"in 7 days."}'::jsonb,NULL),
('ai-commercial-60s','AI Commercial, 60s','video-ads','A longer brand story on the same pipeline, for when 30 seconds is not enough.','The same character-locked pipeline as our 30s commercial, with room for a full story arc. Built for brand films, launches and big screens.',ARRAY['Concept, script, character and location sheets','60s master film','4 cutdowns: 30s, 15s, 6s and 9:16','Captions']::text[],460,680,'project','USD','quote',true,false,false,2,ARRAY['Real estate developers','Banks and financial services','Hospitals and education','Companies telling their brand story or mission']::text[],ARRAY['You want to tell your brand''s history or mission','The story has several characters or features','It will run as a YouTube pre-roll or on an event screen']::text[],ARRAY['Product or project photos','Your brand story or mission','Logo and colours']::text[],'16:9, 9:16, 1:1','7 days',ARRAY['brand','corp','launch']::text[],ARRAY['ai-commercial-30s','corporate-avc-event-video']::text[],NULL,'{"lead":"Tell your brand story","accent":"without","rest":"a film crew."}'::jsonb,NULL),
('ai-ugc-ads','AI UGC Ads','video-ads','Creator-style hook videos that look filmed on a phone, without hiring creators.','Videos that feel like a real person reviewing your product on their phone. You get several hooks and several AI creators, so you can test what your audience trusts.',ARRAY['3 different hooks per script','3 AI creators matched to your target age and look','Handheld, phone-style camera','Captions','9:16 and 1:1 versions']::text[],70,250,'project','USD','quote',true,true,false,3,ARRAY['Skincare and haircare','Gadgets and accessories','Facebook commerce pages','Apps and food delivery']::text[],ARRAY['Polished ads are not converting and your audience trusts real-looking content','You want to test many hooks quickly','Influencer fees and schedules are slowing you down']::text[],ARRAY['Product photos or video','Real customer reviews or comments, if you have them','Who you want to sell to']::text[],'9:16, 1:1','5 days',ARRAY['sales','ecom','launch']::text[],ARRAY['ad-variant-pack','reels-pack-of-6']::text[],NULL,'{"lead":"Creator-style ads","accent":"without","rest":"hiring creators."}'::jsonb,NULL),
('ad-variant-pack','Ad Variant Pack','video-ads','One master ad turned into 10 testable versions.','We take one ad that works and turn it into 10 versions with different hooks, formats, lengths and languages. Meta then finds the winner for you.',ARRAY['10 variants across hooks, formats, lengths and languages','File names ready for Ads Manager','A sheet showing what each variant tests']::text[],85,220,'project','USD','quote',true,false,false,4,ARRAY['Brands running Meta ads every month','Performance marketers','Ad agencies']::text[],ARRAY['Your best ad is getting tired and clicks are dropping','You want to test which hook or length works best','Different audiences need different openings']::text[],ARRAY['A master ad, ours or yours','The audiences you will run it to']::text[],'16:9, 9:16, 1:1','5 days',ARRAY['sales','ecom']::text[],ARRAY['ad-performance-review','ai-ugc-ads']::text[],NULL,'{"lead":"Turn one ad into","accent":"ten","rest":"winning versions."}'::jsonb,NULL),
('product-film','Product Film','video-ads','A software-style launch film with UI, bold type and motion.','A sleek launch film for tech products, made with interface animation, large typography and motion. Built to impress on launch day and to work as a website hero video.',ARRAY['30 to 60s film','9:16 version','Music and sound effects']::text[],140,250,'project','USD','quote',true,false,false,5,ARRAY['Software companies','Mobile apps','Gadget brands']::text[],ARRAY['You have a product launch coming','You need a hero video for your website','You are pitching investors']::text[],ARRAY['App screenshots or Figma files','Logo and colours','Your top 3 features']::text[],'16:9, 9:16','5 days',ARRAY['tech','launch']::text[],ARRAY['saas-explainer','motion-ad-logo-animation']::text[],'Product Film impresses people on launch day. SaaS Explainer and App Demo teaches them how to use the product.','{"lead":"Launch your product","accent":"like a keynote","rest":"."}'::jsonb,NULL),
('saas-explainer','SaaS Explainer and App Demo','video-ads','A step-by-step explainer that shows what your software does in 60 to 90 seconds.','We turn your software into a clear story: the problem, how your product solves it, and the key screens in action. Ideal for your website, sales calls and onboarding.',ARRAY['Problem-to-solution script','Storyboard approval before production','UI animation from your Figma files or screen recordings, with zoom-ins and callouts','Voiceover','Onboarding cut with a short clip for each feature','Lottie animation for your website']::text[],220,330,'project','USD','quote',true,false,true,6,ARRAY['SaaS, ERP and POS software','School and coaching management software','Fintech and e-commerce tools','Automation services']::text[],ARRAY['You repeat the same demo on every sales call','People sign up but never start using the product','Visitors land on your website and leave confused']::text[],ARRAY['App link or a demo login','Screenshots or Figma files','Your customer''s biggest problem and your top 3 features']::text[],'16:9, 9:16','7 days',ARRAY['tech','edu']::text[],ARRAY['product-film','explainer-motion-graphics']::text[],'Product Film impresses people on launch day. SaaS Explainer and App Demo teaches them how to use the product.','{"lead":"Show what your software does","accent":"in 90 seconds","rest":"."}'::jsonb,NULL),
('cgi-product-commercial','CGI Product Commercial','video-ads','Your product as the hero, with splashes, smoke and premium light. No people needed.','A CGI-style commercial where the product is the star: liquid splashes, smoke, pieces coming together and studio lighting. Your label, colour and shape stay exactly as they are.',ARRAY['10 to 20s CGI film','Label, colour and shape matched to your real product','3 formats','Sound design','Loop version for social']::text[],140,260,'project','USD','quote',true,false,true,7,ARRAY['Beverages and juices','Perfume and skincare','Watches and gadgets','Snacks and packaged food']::text[],ARRAY['You want your product to look premium','You need a 5 to 10 second scroll-stopper','You do not want the cost or hassle of models']::text[],ARRAY['Clear photos of the product from every side','High-resolution label artwork']::text[],'16:9, 9:16, 1:1','5 days',ARRAY['sales','launch','brand']::text[],ARRAY['ai-product-photoshoot','ai-commercial-30s']::text[],NULL,'{"lead":"Make your product","accent":"the hero","rest":"of every frame."}'::jsonb,NULL),
('festival-campaign-pack','Festival Campaign Pack','video-ads','A complete ad set for Eid, Puja, Pohela Boishakh, 11.11 or Black Friday in one theme.','One festive theme across every placement: a hero ad, offer reels, static posts and page assets. Book 3 to 4 weeks before the festival so your ads have time to learn.',ARRAY['1 hero ad, 20 to 30s','3 offer reels','5 static posts','Cover photo and profile frame','One colour and type system across the whole set']::text[],340,590,'project','USD','quote',true,false,true,8,ARRAY['Fashion and footwear','Restaurants and food','Electronics','Facebook commerce pages']::text[],ARRAY['A festival is 3 to 4 weeks away','You have one offer and want it to look the same everywhere']::text[],ARRAY['Offer details and campaign dates','Product list and photos']::text[],'16:9, 9:16, 1:1, 4:5','7 days',ARRAY['festival','sales','fashion','ecom']::text[],ARRAY['static-ad-creative-pack','reels-pack-of-6']::text[],NULL,'{"lead":"Your Eid and Puja campaign,","accent":"ready","rest":"before the rush."}'::jsonb,NULL),
('ai-storyboard-animatic','AI Storyboard and Animatic','video-ads','A moving draft of your whole ad, so you can get approval before production.','We turn an idea or script into a shot-by-shot storyboard and a rough animated cut with temporary voice and music. Perfect for pitches and for planning a shoot.',ARRAY['Shot-by-shot storyboard, 12 to 20 frames','Animatic video with temporary voice and music','Shot list PDF']::text[],95,170,'project','USD','quote',true,false,true,9,ARRAY['Ad agencies','Brand marketing teams','Production houses','Anyone pitching an idea']::text[],ARRAY['You need to pitch a concept','You want a shot plan before a live shoot','Your boss cannot picture the idea from a script']::text[],ARRAY['The idea or script','References, if you have them']::text[],'16:9','3 days',ARRAY['corp','brand']::text[],ARRAY['ai-commercial-30s','ai-commercial-60s']::text[],NULL,'{"lead":"See the whole ad","accent":"before","rest":"you spend on it."}'::jsonb,NULL),
('ai-product-photoshoot','AI Product Photoshoot','imagery','Studio, lifestyle and seasonal product shots without a studio or photographer.','Premium product images in three different scenes, retouched and ready for your page, ads and website. Your product stays exactly as it is.',ARRAY['12 images per product across 3 scenes','Retouched','PSD on request','Product kept exactly as it is']::text[],50,85,'product','USD','quote',true,false,false,10,ARRAY['Skincare','Food and drink','Home decor','Gadgets and handicrafts']::text[],ARRAY['Your page photos look cheap','You need fresh images every season','You want the same product shown in different settings']::text[],ARRAY['Clear product photos or a sample','The mood you want']::text[],'4:5, 1:1','3 days',ARRAY['ecom','sales','launch']::text[],ARRAY['ecommerce-catalogue-pack','static-ad-creative-pack']::text[],'Product Photoshoot gives you ad-ready scenes. E-commerce Catalogue Pack gives you many products on clean backgrounds. Virtual Try-On puts your clothing on a model.','{"lead":"Studio product photos","accent":"without","rest":"the studio."}'::jsonb,NULL),
('fashion-film-lookbook','Fashion Film and Lookbook','imagery','A runway-style film and a full lookbook for your new collection, without a model shoot.','A 30 second fashion film plus 20 lookbook images with AI models. Fabric, cut and colour stay true to the real garment.',ARRAY['30s fashion film','20 lookbook images','3 AI models','Fabric, cut and colour true to the real garment']::text[],290,450,'project','USD','quote',true,false,false,11,ARRAY['Clothing brands','Boutiques','Jewellery']::text[],ARRAY['You are launching a new collection','A new season is starting','You are opening a showroom']::text[],ARRAY['Front and back photos of each garment','Fabric close-ups']::text[],'16:9, 9:16, 4:5','7 days',ARRAY['fashion','launch','brand']::text[],ARRAY['virtual-try-on','ai-brand-model']::text[],NULL,'{"lead":"Launch your collection","accent":"on the runway","rest":"with no model shoot."}'::jsonb,NULL),
('ai-brand-model','AI Brand Model','imagery','A consistent model who belongs only to your brand.','A custom AI model with the same face in every image, created only for you. We never offer your model to another client.',ARRAY['Model sheet: face, body and 6 expressions','10 images','Exclusive usage rights, never given to another client']::text[],75,140,'project','USD','quote',true,false,false,12,ARRAY['Fashion','Skincare','Jewellery','Brands posting content every month']::text[],ARRAY['Your model changes with every shoot','Model fees and schedules are a hassle','You want a face customers recognise']::text[],ARRAY['The look you want: age, style and attitude','Your brand mood']::text[],'4:5, 1:1','5 days',ARRAY['fashion','brand']::text[],ARRAY['ai-brand-ambassador','fashion-film-lookbook']::text[],'AI Brand Model is a one-time job: one face and 10 images. AI Brand Ambassador is a monthly service with a personality, a voice, posts and reels.','{"lead":"A face that belongs","accent":"only","rest":"to your brand."}'::jsonb,NULL),
('virtual-try-on','Virtual Try-On and Model Swap','imagery','Turn flat-lay or mannequin photos into real-looking on-model images.','Send us clothes on a hanger or on the floor and get them back worn by models, from every angle. No shoot, no model fees, and it scales to hundreds of products.',ARRAY['10 images per product: front, side, back and close-up','2 to 3 models','One consistent background theme','Optional 5s movement clip']::text[],35,70,'product','USD','quote',true,true,true,13,ARRAY['Facebook commerce clothing pages','Saree, three-piece and panjabi sellers','Kidswear','Wholesalers']::text[],ARRAY['You have hundreds of products and cannot shoot them all','You want to show different ages or body types']::text[],ARRAY['Flat-lay or mannequin photos','Fabric close-ups']::text[],'4:5, 1:1, 9:16','2 days',ARRAY['fashion','ecom']::text[],ARRAY['ecommerce-catalogue-pack','fashion-film-lookbook']::text[],'Product Photoshoot gives you ad-ready scenes. E-commerce Catalogue Pack gives you many products on clean backgrounds. Virtual Try-On puts your clothing on a model.','{"lead":"Put your clothes","accent":"on a model","rest":"without a shoot."}'::jsonb,NULL),
('ecommerce-catalogue-pack','E-commerce Catalogue Pack','imagery','Clean, consistent white-background images for many products at once.','Phone photos in, a marketplace-ready catalogue out. Every image matches in background, shadow and colour, sized for your website, Daraz and Facebook.',ARRAY['20 SKUs per pack','White or brand-colour background','Shadows and colour corrected','Exports sized for Daraz, website and Facebook','Files named by SKU']::text[],55,95,'pack of 20 products','USD','quote',true,false,true,14,ARRAY['Online shops','Daraz sellers','Wholesalers','Superstores']::text[],ARRAY['Every product photo looks different','Your photos are shot on a phone','Marketplaces reject your image sizes']::text[],ARRAY['Phone photos of each product in good light','Your SKU list']::text[],'1:1','3 days',ARRAY['ecom']::text[],ARRAY['ai-product-photoshoot','virtual-try-on']::text[],'Product Photoshoot gives you ad-ready scenes. E-commerce Catalogue Pack gives you many products on clean backgrounds. Virtual Try-On puts your clothing on a model.','{"lead":"Clean catalogue photos","accent":"for every","rest":"product you sell."}'::jsonb,NULL),
('static-ad-creative-pack','Static Ad Creative Pack','imagery','10 image ads and a carousel with a clear message and correct Bangla text.','Ten static ads built around different angles, plus a carousel. Bangla text is set by a designer and never generated by AI, so it is always correct.',ARRAY['10 statics across angles: problem, offer, review, comparison and question','1 carousel','Bangla text set by hand','Ad copy and headline for each']::text[],85,140,'project','USD','quote',true,false,true,15,ARRAY['Any business running Meta ads','Brands starting on a small budget','Coaching centres, clinics and service businesses']::text[],ARRAY['You do not have a video budget yet','You want to test many angles fast','You need offer posts']::text[],ARRAY['Your offer or main message','Product photos','Logo and colours']::text[],'4:5, 1:1, 9:16','3 days',ARRAY['sales','ecom','festival']::text[],ARRAY['festival-campaign-pack','ad-variant-pack']::text[],NULL,'{"lead":"Ten image ads","accent":"that say it clearly","rest":"."}'::jsonb,NULL),
('3d-product-360','3D Product Model and 360 View','imagery','A 3D model of your product that customers can spin on your website.','A reusable 3D model with a 360 turntable video and a web-ready viewer. Use it on your site today and in CGI ads tomorrow.',ARRAY['GLB or USDZ 3D file','360 turntable video','Embed code for your website','5 rendered images']::text[],70,140,'product','USD','quote',true,false,true,16,ARRAY['Furniture and interiors','Electronics','Shoes and bags','Packaging']::text[],ARRAY['Customers want to see every side','The product is not made yet but you want pre-orders','You need a base for CGI ads']::text[],ARRAY['Photos from all around the product, or design files with dimensions']::text[],'GLB, USDZ, MP4','5 days',ARRAY['ecom','launch','tech']::text[],ARRAY['cgi-product-commercial','ai-product-photoshoot']::text[],NULL,'{"lead":"Let customers","accent":"spin","rest":"your product before they buy."}'::jsonb,NULL),
('digital-clone','Digital Clone','people','Your own face and voice, cloned with consent, so you can post without filming.','A digital twin made from a 3 minute recording and your written consent. Post regular videos in Bangla and English without sitting in front of a camera every week.',ARRAY['Setup from a 3 minute recording and written consent','4 videos per month','Bangla and English','Your clone is used only with your approval']::text[],140,220,'month','USD','monthly',true,false,false,17,ARRAY['CEOs and founders','Doctors, lawyers and consultants','Coaches and teachers','Real estate agents']::text[],ARRAY['You want to post videos but have no time','Filming every week is not realistic','You want content in both Bangla and English']::text[],ARRAY['A 3 minute video in good light','Signed consent form','Topics for the month']::text[],'16:9, 9:16','5 days setup',ARRAY['creator','corp','edu']::text[],ARRAY['ai-presenter-video','ai-voiceover']::text[],'Digital Clone is you, with your own face and voice. AI Presenter is a new face, for when you would rather not appear.','{"lead":"Post every week","accent":"without","rest":"filming every week."}'::jsonb,NULL),
('ai-presenter-video','AI Presenter Video','people','An AI presenter explains your product or service on camera.','A professional presenter speaks to camera with on-screen graphics and text. Complex products become easy to understand.',ARRAY['Script','AI presenter of your choice','60 to 90s video','Background graphics and text','Captions']::text[],110,170,'video','USD','quote',true,false,false,18,ARRAY['Banks and insurance','Hospitals','Edtech','Government and NGO projects']::text[],ARRAY['You do not want to appear on camera yourself','You need to explain rules or terms','You need an intro video for your website or page']::text[],ARRAY['What you want explained','Logo and colours']::text[],'16:9, 9:16','5 days',ARRAY['corp','edu','tech']::text[],ARRAY['digital-clone','training-video']::text[],'Digital Clone is you, with your own face and voice. AI Presenter is a new face, for when you would rather not appear.','{"lead":"A presenter who explains","accent":"your product","rest":"on camera."}'::jsonb,NULL),
('training-video','Training Video','people','Training modules for staff or customers, with slides and a presenter.','We turn your SOPs and know-how into clear 5 to 8 minute modules your team can watch anytime. Train every branch the same way.',ARRAY['5 to 8 minute modules','Slides and presenter','Chapters','Bangla or English']::text[],95,150,'module','USD','quote',true,false,false,19,ARRAY['Corporate HR','Factory safety training','Banks and franchises','Online courses']::text[],ARRAY['You repeat the same training for every new hire','You have many branches and few trainers','You want to build a course']::text[],ARRAY['Training content or SOPs','Number of modules']::text[],'16:9','7 days per 5 modules',ARRAY['edu','corp']::text[],ARRAY['ai-presenter-video','explainer-motion-graphics']::text[],NULL,'{"lead":"Train every branch","accent":"the same way","rest":", anytime."}'::jsonb,NULL),
('ai-brand-ambassador','AI Brand Ambassador','people','A virtual face for your brand who shows up every month, like a real ambassador.','A character with a name, personality and voice who appears in your posts and reels every month. Fully exclusive to your brand.',ARRAY['Character, name, personality and voice','8 posts and 4 reels every month','Monthly content calendar','Exclusive rights']::text[],230,390,'month','USD','monthly',true,false,true,20,ARRAY['Skincare','Telecom and apps','Food brands','Brands that post every day']::text[],ARRAY['A celebrity ambassador is out of budget','You need a lot of content every month','You want your brand to have a personality']::text[],ARRAY['Your brand mood and audience','Products and offers for the month']::text[],'9:16, 4:5','Monthly',ARRAY['brand','creator','sales']::text[],ARRAY['ai-brand-model','monthly-content-subscription']::text[],'AI Brand Model is a one-time job: one face and 10 images. AI Brand Ambassador is a monthly service with a personality, a voice, posts and reels.','{"lead":"A brand ambassador","accent":"who never","rest":"misses a post."}'::jsonb,NULL),
('ai-corporate-headshots','AI Corporate Headshots','people','Matching professional headshots for your whole team, without a photographer.','Send selfies and get studio-quality portraits back. Everyone gets the same background, light and style.',ARRAY['5 images per person','Same background, lighting and outfit style','Sizes for website and LinkedIn']::text[],15,25,'person','USD','quote',true,false,true,21,ARRAY['Corporate offices','Startups','Law firms and hospitals','Schools and colleges']::text[],ARRAY['Your website needs a team page','Your team needs LinkedIn profile photos','You are making ID cards','Your team works from different places']::text[],ARRAY['8 to 10 casual selfies per person']::text[],'1:1, 4:5','2 days',ARRAY['corp','creator']::text[],ARRAY['digital-clone']::text[],NULL,'{"lead":"Matching team photos","accent":"from","rest":"simple selfies."}'::jsonb,NULL),
('reels-pack-of-6','Reels Pack of 6','social','Six reels from one brief to keep your page active all month.','Six short reels, each with its own hook, captions and cover, planned around your business. One brief, a month of content.',ARRAY['6 reels, 15 to 30s each','A different hook for each reel','Captions','Cover images','Post captions written for you']::text[],170,370,'pack of 6','USD','quote',true,true,false,22,ARRAY['Restaurants and cafes','Facebook commerce','Coaching centres','Salons and gyms']::text[],ARRAY['Your page has no regular content','Your reach is dropping','You do not know what to make reels about']::text[],ARRAY['Business details and offers','Photos or footage, if you have them']::text[],'9:16','5 days',ARRAY['sales','ecom','creator']::text[],ARRAY['monthly-content-subscription','ai-ugc-ads']::text[],'Reels Pack of 6 is a one-time order. Monthly Content Subscription gives you a set amount every month with a dedicated manager.','{"lead":"A month of reels","accent":"from","rest":"one brief."}'::jsonb,NULL),
('ai-video-editing','AI Video Editing','social','Your raw footage turned into a finished, professional cut.','Cutting, pacing, colour grading, voice cleanup, captions and sound effects. Priced per minute of final video.',ARRAY['Cut and pacing','Cinematic colour grade','Voice cleanup','Captions','Sound effects']::text[],15,30,'minute','USD','per-minute',true,false,false,23,ARRAY['YouTubers','Podcasts','Events','Companies with footage but no editor']::text[],ARRAY['You have shot on a phone or camera','You do not have the time or skills to edit']::text[],ARRAY['Raw footage','Transcript or key points','References, if you have them']::text[],'16:9, 9:16, 1:1','3 days',ARRAY['creator','corp']::text[],ARRAY['long-to-short-repurposing','youtube-channel-pack']::text[],NULL,'{"lead":"Your raw footage,","accent":"finished","rest":"like a pro edit."}'::jsonb,NULL),
('motion-ad-logo-animation','Motion Ad or Logo Animation','social','Kinetic type, logo reveals and product motion in 10 to 20 seconds.','Short, polished animation for intros, outros, offers and announcements. Eye-catching without any footage.',ARRAY['10 to 20s animation','3 formats','After Effects source file on request']::text[],45,90,'project','USD','quote',true,false,false,24,ARRAY['New brands','YouTube channels','Events','Software companies']::text[],ARRAY['You need a logo at the start or end of your videos','You want to announce an offer fast','You want something eye-catching without footage']::text[],ARRAY['Logo vector file (AI, SVG or PDF)','Your message or offer']::text[],'16:9, 9:16, 1:1','4 days',ARRAY['brand','launch']::text[],ARRAY['explainer-motion-graphics','product-film']::text[],'Motion Ad is a 10 to 20 second burst for a logo or an offer. Explainer Motion Graphics runs 1 to 2 minutes and explains data or a process.','{"lead":"Bring your logo","accent":"to life","rest":"in 15 seconds."}'::jsonb,NULL),
('explainer-motion-graphics','Explainer Motion Graphics','social','A 1 to 2 minute infographic video that makes data or a process easy to follow.','Charts, icons, glass UI cards and kinetic text that turn numbers, reports and complex ideas into something anyone understands. No footage needed.',ARRAY['Script','Style frames for approval','Glass UI cards, charts and icon animation','Voiceover','Music and sound effects']::text[],190,330,'project','USD','quote',true,false,true,25,ARRAY['NGOs and development projects','Edtech','Banks and finance','Educational YouTube channels']::text[],ARRAY['You need to present data or a report','You need to explain a process, such as how to apply for a loan','There is no footage to show']::text[],ARRAY['Your data, report or content','Logo and colours']::text[],'16:9, 9:16','7 days',ARRAY['corp','edu','tech']::text[],ARRAY['saas-explainer','corporate-avc-event-video']::text[],'Motion Ad is a 10 to 20 second burst for a logo or an offer. Explainer Motion Graphics runs 1 to 2 minutes and explains data or a process.','{"lead":"Make your numbers","accent":"easy","rest":"to understand."}'::jsonb,NULL),
('long-to-short-repurposing','Long to Short Repurposing','social','Your podcast, webinar or live stream cut into 10 to 15 short videos.','We find the best moments in your long video and turn them into vertical clips with hooks and animated captions. One recording, weeks of shorts.',ARRAY['10 to 15 clips, 30 to 60s each','A hook title on every clip','Animated captions','Face-tracked 9:16 crop','Covers']::text[],70,120,'project','USD','quote',true,false,true,26,ARRAY['Podcasters','Coaches and speakers','YouTubers','Companies running webinars']::text[],ARRAY['You have hour-long videos nobody watches in full','You need shorts every week']::text[],ARRAY['The long video file or link']::text[],'9:16, 1:1','3 days',ARRAY['creator','edu']::text[],ARRAY['ai-video-editing','youtube-channel-pack']::text[],NULL,'{"lead":"Turn one long video","accent":"into weeks","rest":"of shorts."}'::jsonb,NULL),
('corporate-avc-event-video','Corporate AVC and Event Video','social','Audio visual presentations for AGMs, anniversaries, launches and event screens.','Your company''s story, milestones and numbers on the big screen, plus an opener that sets the tone for the event.',ARRAY['2 to 5 minute AVC','History, milestones and number graphics','Event opener','Voiceover','4K export']::text[],280,580,'project','USD','quote',true,false,true,27,ARRAY['Corporates and banks','Schools and colleges','NGOs','Event management companies']::text[],ARRAY['An AGM or annual event is coming','You are inaugurating a project','It will play on a large stage screen']::text[],ARRAY['Company information, photos and figures','Event date']::text[],'16:9','7 days',ARRAY['corp']::text[],ARRAY['ai-commercial-60s','explainer-motion-graphics']::text[],NULL,'{"lead":"Your company story","accent":"on the big screen","rest":"."}'::jsonb,NULL),
('youtube-channel-pack','YouTube Thumbnail and Channel Pack','social','Thumbnails, banner, intro and outro in one consistent style.','A channel that looks like a brand, with thumbnails designed to earn the click.',ARRAY['10 thumbnails','Channel banner and profile image','5s intro and 10s outro','Thumbnail template']::text[],70,110,'project','USD','quote',true,false,true,28,ARRAY['YouTubers','Coaching centres','News pages','Podcasts']::text[],ARRAY['Your videos are good but clicks are low','Your channel looks messy','You are starting a new channel']::text[],ARRAY['Your channel link','A few photos of you']::text[],'16:9','2 days',ARRAY['creator']::text[],ARRAY['long-to-short-repurposing','ai-video-editing']::text[],NULL,'{"lead":"Thumbnails people","accent":"actually click","rest":"."}'::jsonb,NULL),
